TVCT_DB.getAll = function() { return this.articles; };
TVCT_DB.getById = function(id) {
    const numericId = parseInt(id, 10);
    return this.articles.find(a => a.id === numericId) || this.articles[0];
};
TVCT_DB.getByCategory = function(catSlug) {
    if (!catSlug || catSlug === 'all') return this.articles;
    return this.articles.filter(a => a.category_slug === catSlug);
};
TVCT_DB.getRelated = function(currentId, limit = 8) {
    const current = this.getById(currentId);
    return this.articles
        .filter(a => a.id !== current.id && (a.category_slug === current.category_slug || a.category === current.category))
        .slice(0, limit);
};
TVCT_DB.getPopular = function(limit = 10) {
    return [...this.articles].sort((a, b) => b.views - a.views).slice(0, limit);
};
TVCT_DB.getLatest = function(limit = 15) {
    return [...this.articles].slice(0, limit);
};
TVCT_DB.getVideos = function(limit = 8) {
    return this.articles.filter(a => a.has_video).slice(0, limit);
};
TVCT_DB.search = function(query, catSlug = '', author = '', sort = 'newest') {
    let results = this.articles;
    if (query) {
        const q = query.toLowerCase().trim();
        results = results.filter(a => 
            a.title.toLowerCase().includes(q) || 
            a.excerpt.toLowerCase().includes(q) ||
            a.tags.some(t => t.toLowerCase().includes(q))
        );
    }
    if (catSlug && catSlug !== 'all') {
        results = results.filter(a => a.category_slug === catSlug);
    }
    if (author && author !== 'all') {
        results = results.filter(a => a.author.toLowerCase().includes(author.toLowerCase()));
    }
    if (sort === 'views') {
        results.sort((a, b) => b.views - a.views);
    } else {
        results.sort((a, b) => b.id - a.id);
    }
    return results;
};
TVCT_DB.validateComment = function(body) {
    const lower = body.toLowerCase();
    const foundBanned = this.banned_keywords.filter(word => lower.includes(word));
    return {
        isValid: foundBanned.length === 0,
        bannedWords: foundBanned
    };
};
